-- A superseded GitHub push ends its operation cancelled. Its provider mutation claim is released in the same batch, and
-- the delete guard of the claim must admit that release, or the cancelled operation keeps the project from every later
-- deployment, rename, data change and deletion. The guard admits the claim of a cancelled operation only when the operation
-- ended as a superseded push whose candidate cleanup is evidenced (nothing the operation started is left at the provider),
-- its Workflow run is completed without an active reconciliation attempt, its deployment is closed, no
-- reconciliation attempt stayed unknown, and no placement or bucket reservation or Native database create is open. The batch
-- guard in deployment-cleanup.ts enforces the same closure before it deletes the claim.
--
-- Rollout: apply this migration to Core BEFORE the Worker that releases the claim, because that Worker's delete is refused
-- by the earlier guard. A Worker that still cancels without releasing during the overlap strands one claim. Applying this
-- file again releases it, because every statement below only acts on what is not closed yet.
DROP TRIGGER product_provider_mutation_claims_delete_guard;
CREATE TRIGGER product_provider_mutation_claims_delete_guard BEFORE DELETE ON product_provider_mutation_claims
WHEN NOT EXISTS(SELECT 1 FROM operations operation WHERE operation.organization_id=OLD.organization_id AND operation.project_id=OLD.project_id AND operation.operation_id=OLD.operation_id AND operation.state IN ('succeeded','failed'))
 AND NOT EXISTS(SELECT 1 FROM product_provider_reconciliation_attempts attempt WHERE attempt.mode='abandon' AND attempt.outcome='resolved_absent' AND attempt.claim_id=OLD.claim_id AND attempt.organization_id=OLD.organization_id AND attempt.project_id=OLD.project_id AND attempt.environment_id=OLD.environment_id AND attempt.operation_id=OLD.operation_id AND attempt.event_id=OLD.event_id AND attempt.billing_epoch_id=OLD.billing_epoch_id AND attempt.logical_workflow_id=OLD.logical_workflow_id AND attempt.event_type=OLD.event_type AND attempt.accepted_lifecycle_version=OLD.accepted_lifecycle_version)
 AND NOT ( EXISTS(SELECT 1 FROM operations cancelled WHERE cancelled.organization_id=OLD.organization_id AND cancelled.project_id=OLD.project_id AND cancelled.operation_id=OLD.operation_id AND cancelled.state='cancelled')
 AND EXISTS(SELECT 1 FROM github_push_deployments push WHERE push.organization_id=OLD.organization_id AND push.project_id=OLD.project_id AND push.operation_id=OLD.operation_id AND push.state='superseded' AND push.cleanup_required=0)
 AND EXISTS(SELECT 1 FROM wfp_candidate_receipts candidate WHERE candidate.organization_id=OLD.organization_id AND candidate.project_id=OLD.project_id AND candidate.operation_id=OLD.operation_id)
 AND NOT EXISTS(SELECT 1 FROM wfp_candidate_receipts candidate WHERE candidate.organization_id=OLD.organization_id AND candidate.project_id=OLD.project_id AND candidate.operation_id=OLD.operation_id
  AND (NOT EXISTS(SELECT 1 FROM wfp_candidate_cleanup_requests request JOIN wfp_candidate_cleanup_receipts cleanup ON cleanup.candidate_receipt_id=request.candidate_receipt_id WHERE request.candidate_receipt_id=candidate.candidate_receipt_id)
   OR EXISTS(SELECT 1 FROM wfp_candidate_cleanup_resource_expectations expected WHERE expected.candidate_receipt_id=candidate.candidate_receipt_id AND NOT EXISTS(SELECT 1 FROM wfp_candidate_operation_cleanup_receipts actual WHERE actual.cleanup_request_id=expected.cleanup_request_id AND actual.provider=expected.provider AND actual.resource_kind=expected.resource_kind AND actual.resource_identity_sha256=expected.resource_identity_sha256))
   OR EXISTS(SELECT 1 FROM wfp_candidate_operation_cleanup_receipts actual WHERE actual.candidate_receipt_id=candidate.candidate_receipt_id AND NOT EXISTS(SELECT 1 FROM wfp_candidate_cleanup_resource_expectations expected WHERE expected.cleanup_request_id=actual.cleanup_request_id AND expected.provider=actual.provider AND expected.resource_kind=actual.resource_kind AND expected.resource_identity_sha256=actual.resource_identity_sha256))))
 AND NOT EXISTS(SELECT 1 FROM product_provider_reconciliation_attempts attempt WHERE attempt.organization_id=OLD.organization_id AND attempt.project_id=OLD.project_id AND attempt.operation_id=OLD.operation_id AND attempt.outcome='unknown')
 AND NOT EXISTS(SELECT 1 FROM neon_project_placement_reservations placement WHERE placement.organization_id=OLD.organization_id AND placement.project_id=OLD.project_id AND placement.operation_id=OLD.operation_id)
 AND NOT EXISTS(SELECT 1 FROM project_r2_bucket_reservations bucket WHERE bucket.organization_id=OLD.organization_id AND bucket.project_id=OLD.project_id AND bucket.operation_id=OLD.operation_id)
 AND NOT EXISTS(SELECT 1 FROM native_auth_database_operations native_create WHERE native_create.organization_id=OLD.organization_id AND native_create.project_id=OLD.project_id AND native_create.operation_id=OLD.operation_id AND native_create.state IN ('reserved','dispatched'))
 AND NOT EXISTS(SELECT 1 FROM product_workflow_runs run WHERE run.organization_id=OLD.organization_id AND run.project_id=OLD.project_id AND run.operation_id=OLD.operation_id AND (run.state<>'completed' OR run.active_reconciliation_attempt_id IS NOT NULL))
 AND NOT EXISTS(SELECT 1 FROM deployments deployment WHERE deployment.organization_id=OLD.organization_id AND deployment.project_id=OLD.project_id AND deployment.operation_id=OLD.operation_id AND deployment.status NOT IN ('succeeded','failed')))
BEGIN SELECT RAISE(ABORT,'active product provider mutation claim cannot be deleted'); END;

-- Close what the cancellations before this migration left behind, for exactly the operations whose claim may then be released.
UPDATE product_workflow_runs SET state='completed',
 terminal_evidence=json_object('errorCode','SUPERSEDED','supersededById',(SELECT push.superseded_by_id FROM github_push_deployments push WHERE push.organization_id=product_workflow_runs.organization_id AND push.project_id=product_workflow_runs.project_id AND push.operation_id=product_workflow_runs.operation_id)),
 active_replay_attempt_id=NULL, completed_at=updated_at
WHERE state='queued' AND active_reconciliation_attempt_id IS NULL
 AND EXISTS(SELECT 1 FROM operations cancelled WHERE cancelled.organization_id=product_workflow_runs.organization_id AND cancelled.project_id=product_workflow_runs.project_id AND cancelled.operation_id=product_workflow_runs.operation_id AND cancelled.state='cancelled')
 AND EXISTS(SELECT 1 FROM github_push_deployments push WHERE push.organization_id=product_workflow_runs.organization_id AND push.project_id=product_workflow_runs.project_id AND push.operation_id=product_workflow_runs.operation_id AND push.state='superseded' AND push.cleanup_required=0)
 AND EXISTS(SELECT 1 FROM wfp_candidate_receipts candidate WHERE candidate.organization_id=product_workflow_runs.organization_id AND candidate.project_id=product_workflow_runs.project_id AND candidate.operation_id=product_workflow_runs.operation_id)
 AND NOT EXISTS(SELECT 1 FROM wfp_candidate_receipts candidate WHERE candidate.organization_id=product_workflow_runs.organization_id AND candidate.project_id=product_workflow_runs.project_id AND candidate.operation_id=product_workflow_runs.operation_id
  AND (NOT EXISTS(SELECT 1 FROM wfp_candidate_cleanup_requests request JOIN wfp_candidate_cleanup_receipts cleanup ON cleanup.candidate_receipt_id=request.candidate_receipt_id WHERE request.candidate_receipt_id=candidate.candidate_receipt_id)
   OR EXISTS(SELECT 1 FROM wfp_candidate_cleanup_resource_expectations expected WHERE expected.candidate_receipt_id=candidate.candidate_receipt_id AND NOT EXISTS(SELECT 1 FROM wfp_candidate_operation_cleanup_receipts actual WHERE actual.cleanup_request_id=expected.cleanup_request_id AND actual.provider=expected.provider AND actual.resource_kind=expected.resource_kind AND actual.resource_identity_sha256=expected.resource_identity_sha256))
   OR EXISTS(SELECT 1 FROM wfp_candidate_operation_cleanup_receipts actual WHERE actual.candidate_receipt_id=candidate.candidate_receipt_id AND NOT EXISTS(SELECT 1 FROM wfp_candidate_cleanup_resource_expectations expected WHERE expected.cleanup_request_id=actual.cleanup_request_id AND expected.provider=actual.provider AND expected.resource_kind=actual.resource_kind AND expected.resource_identity_sha256=actual.resource_identity_sha256))))
 AND NOT EXISTS(SELECT 1 FROM product_provider_reconciliation_attempts attempt WHERE attempt.organization_id=product_workflow_runs.organization_id AND attempt.project_id=product_workflow_runs.project_id AND attempt.operation_id=product_workflow_runs.operation_id AND attempt.outcome='unknown')
 AND NOT EXISTS(SELECT 1 FROM neon_project_placement_reservations placement WHERE placement.organization_id=product_workflow_runs.organization_id AND placement.project_id=product_workflow_runs.project_id AND placement.operation_id=product_workflow_runs.operation_id)
 AND NOT EXISTS(SELECT 1 FROM project_r2_bucket_reservations bucket WHERE bucket.organization_id=product_workflow_runs.organization_id AND bucket.project_id=product_workflow_runs.project_id AND bucket.operation_id=product_workflow_runs.operation_id)
 AND NOT EXISTS(SELECT 1 FROM native_auth_database_operations native_create WHERE native_create.organization_id=product_workflow_runs.organization_id AND native_create.project_id=product_workflow_runs.project_id AND native_create.operation_id=product_workflow_runs.operation_id AND native_create.state IN ('reserved','dispatched'))
 AND NOT EXISTS(SELECT 1 FROM product_workflow_runs run WHERE run.organization_id=product_workflow_runs.organization_id AND run.project_id=product_workflow_runs.project_id AND run.operation_id=product_workflow_runs.operation_id AND (run.state='reconciliation_required' OR run.active_reconciliation_attempt_id IS NOT NULL))
 AND NOT EXISTS(SELECT 1 FROM deployments deployment WHERE deployment.organization_id=product_workflow_runs.organization_id AND deployment.project_id=product_workflow_runs.project_id AND deployment.operation_id=product_workflow_runs.operation_id AND deployment.status='reconciliation_required');
UPDATE deployments SET status='failed'
WHERE status IN ('queued','running')
 AND EXISTS(SELECT 1 FROM operations cancelled WHERE cancelled.organization_id=deployments.organization_id AND cancelled.project_id=deployments.project_id AND cancelled.operation_id=deployments.operation_id AND cancelled.state='cancelled')
 AND EXISTS(SELECT 1 FROM github_push_deployments push WHERE push.organization_id=deployments.organization_id AND push.project_id=deployments.project_id AND push.operation_id=deployments.operation_id AND push.state='superseded' AND push.cleanup_required=0)
 AND EXISTS(SELECT 1 FROM wfp_candidate_receipts candidate WHERE candidate.organization_id=deployments.organization_id AND candidate.project_id=deployments.project_id AND candidate.operation_id=deployments.operation_id)
 AND NOT EXISTS(SELECT 1 FROM wfp_candidate_receipts candidate WHERE candidate.organization_id=deployments.organization_id AND candidate.project_id=deployments.project_id AND candidate.operation_id=deployments.operation_id
  AND (NOT EXISTS(SELECT 1 FROM wfp_candidate_cleanup_requests request JOIN wfp_candidate_cleanup_receipts cleanup ON cleanup.candidate_receipt_id=request.candidate_receipt_id WHERE request.candidate_receipt_id=candidate.candidate_receipt_id)
   OR EXISTS(SELECT 1 FROM wfp_candidate_cleanup_resource_expectations expected WHERE expected.candidate_receipt_id=candidate.candidate_receipt_id AND NOT EXISTS(SELECT 1 FROM wfp_candidate_operation_cleanup_receipts actual WHERE actual.cleanup_request_id=expected.cleanup_request_id AND actual.provider=expected.provider AND actual.resource_kind=expected.resource_kind AND actual.resource_identity_sha256=expected.resource_identity_sha256))
   OR EXISTS(SELECT 1 FROM wfp_candidate_operation_cleanup_receipts actual WHERE actual.candidate_receipt_id=candidate.candidate_receipt_id AND NOT EXISTS(SELECT 1 FROM wfp_candidate_cleanup_resource_expectations expected WHERE expected.cleanup_request_id=actual.cleanup_request_id AND expected.provider=actual.provider AND expected.resource_kind=actual.resource_kind AND expected.resource_identity_sha256=actual.resource_identity_sha256))))
 AND NOT EXISTS(SELECT 1 FROM product_provider_reconciliation_attempts attempt WHERE attempt.organization_id=deployments.organization_id AND attempt.project_id=deployments.project_id AND attempt.operation_id=deployments.operation_id AND attempt.outcome='unknown')
 AND NOT EXISTS(SELECT 1 FROM neon_project_placement_reservations placement WHERE placement.organization_id=deployments.organization_id AND placement.project_id=deployments.project_id AND placement.operation_id=deployments.operation_id)
 AND NOT EXISTS(SELECT 1 FROM project_r2_bucket_reservations bucket WHERE bucket.organization_id=deployments.organization_id AND bucket.project_id=deployments.project_id AND bucket.operation_id=deployments.operation_id)
 AND NOT EXISTS(SELECT 1 FROM native_auth_database_operations native_create WHERE native_create.organization_id=deployments.organization_id AND native_create.project_id=deployments.project_id AND native_create.operation_id=deployments.operation_id AND native_create.state IN ('reserved','dispatched'))
 AND NOT EXISTS(SELECT 1 FROM product_workflow_runs run WHERE run.organization_id=deployments.organization_id AND run.project_id=deployments.project_id AND run.operation_id=deployments.operation_id AND (run.state='reconciliation_required' OR run.active_reconciliation_attempt_id IS NOT NULL))
 AND NOT EXISTS(SELECT 1 FROM deployments deployment WHERE deployment.organization_id=deployments.organization_id AND deployment.project_id=deployments.project_id AND deployment.operation_id=deployments.operation_id AND deployment.status='reconciliation_required');
DELETE FROM product_provider_mutation_claims
WHERE EXISTS(SELECT 1 FROM operations cancelled WHERE cancelled.organization_id=product_provider_mutation_claims.organization_id AND cancelled.project_id=product_provider_mutation_claims.project_id AND cancelled.operation_id=product_provider_mutation_claims.operation_id AND cancelled.state='cancelled')
 AND EXISTS(SELECT 1 FROM github_push_deployments push WHERE push.organization_id=product_provider_mutation_claims.organization_id AND push.project_id=product_provider_mutation_claims.project_id AND push.operation_id=product_provider_mutation_claims.operation_id AND push.state='superseded' AND push.cleanup_required=0)
 AND EXISTS(SELECT 1 FROM wfp_candidate_receipts candidate WHERE candidate.organization_id=product_provider_mutation_claims.organization_id AND candidate.project_id=product_provider_mutation_claims.project_id AND candidate.operation_id=product_provider_mutation_claims.operation_id)
 AND NOT EXISTS(SELECT 1 FROM wfp_candidate_receipts candidate WHERE candidate.organization_id=product_provider_mutation_claims.organization_id AND candidate.project_id=product_provider_mutation_claims.project_id AND candidate.operation_id=product_provider_mutation_claims.operation_id
  AND (NOT EXISTS(SELECT 1 FROM wfp_candidate_cleanup_requests request JOIN wfp_candidate_cleanup_receipts cleanup ON cleanup.candidate_receipt_id=request.candidate_receipt_id WHERE request.candidate_receipt_id=candidate.candidate_receipt_id)
   OR EXISTS(SELECT 1 FROM wfp_candidate_cleanup_resource_expectations expected WHERE expected.candidate_receipt_id=candidate.candidate_receipt_id AND NOT EXISTS(SELECT 1 FROM wfp_candidate_operation_cleanup_receipts actual WHERE actual.cleanup_request_id=expected.cleanup_request_id AND actual.provider=expected.provider AND actual.resource_kind=expected.resource_kind AND actual.resource_identity_sha256=expected.resource_identity_sha256))
   OR EXISTS(SELECT 1 FROM wfp_candidate_operation_cleanup_receipts actual WHERE actual.candidate_receipt_id=candidate.candidate_receipt_id AND NOT EXISTS(SELECT 1 FROM wfp_candidate_cleanup_resource_expectations expected WHERE expected.cleanup_request_id=actual.cleanup_request_id AND expected.provider=actual.provider AND expected.resource_kind=actual.resource_kind AND expected.resource_identity_sha256=actual.resource_identity_sha256))))
 AND NOT EXISTS(SELECT 1 FROM product_provider_reconciliation_attempts attempt WHERE attempt.organization_id=product_provider_mutation_claims.organization_id AND attempt.project_id=product_provider_mutation_claims.project_id AND attempt.operation_id=product_provider_mutation_claims.operation_id AND attempt.outcome='unknown')
 AND NOT EXISTS(SELECT 1 FROM neon_project_placement_reservations placement WHERE placement.organization_id=product_provider_mutation_claims.organization_id AND placement.project_id=product_provider_mutation_claims.project_id AND placement.operation_id=product_provider_mutation_claims.operation_id)
 AND NOT EXISTS(SELECT 1 FROM project_r2_bucket_reservations bucket WHERE bucket.organization_id=product_provider_mutation_claims.organization_id AND bucket.project_id=product_provider_mutation_claims.project_id AND bucket.operation_id=product_provider_mutation_claims.operation_id)
 AND NOT EXISTS(SELECT 1 FROM native_auth_database_operations native_create WHERE native_create.organization_id=product_provider_mutation_claims.organization_id AND native_create.project_id=product_provider_mutation_claims.project_id AND native_create.operation_id=product_provider_mutation_claims.operation_id AND native_create.state IN ('reserved','dispatched'))
 AND NOT EXISTS(SELECT 1 FROM product_workflow_runs run WHERE run.organization_id=product_provider_mutation_claims.organization_id AND run.project_id=product_provider_mutation_claims.project_id AND run.operation_id=product_provider_mutation_claims.operation_id AND (run.state<>'completed' OR run.active_reconciliation_attempt_id IS NOT NULL))
 AND NOT EXISTS(SELECT 1 FROM deployments deployment WHERE deployment.organization_id=product_provider_mutation_claims.organization_id AND deployment.project_id=product_provider_mutation_claims.project_id AND deployment.operation_id=product_provider_mutation_claims.operation_id AND deployment.status NOT IN ('succeeded','failed'));
